// The launcher every plugin ships as plugin/dist/run, generated by scripts/launcher.mjs: it maps the first
// argument to its entry and runs it on the installed binary, which the launcher itself downloads and
// checksum-verifies during setup. There is no JS
// fallback: with no binary available and none downloadable the launcher says why and exits 127, and a hook
// exits 0 silently, starting one detached download whose lock lives in the version dir. Downloads go to a
// local server through the base override (CORE_DOWNLOAD_BASE); nothing here touches the network. Run with
// `node --test scripts/launcher.test.mjs` (part of npm run check:ci).
import { spawn, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  chmodSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  statSync,
  symlinkSync,
  writeFileSync,
} from "node:fs";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { launcherScript, providerSpec, releaseInfo } from "./launcher.mjs";

/** The release a build embeds in the launcher (releaseInfo's shape). */
const CORE = {
  version: "9.9.9",
  repo: "MuhmdRaouf/claude-code-plugins",
  sha256: {},
};

/** One run of the launcher: its exit status and its output. */
function ran(status, stdout, stderr) {
  return { status, stdout, stderr };
}

/** The fake binary asset the tests serve and install: a shell script printing its name and arguments. */
const asset = (name) => `#!/bin/sh\necho ${name} "$@"\n`;

/** This machine's platform as the launcher computes it, so the served digest matches the embedded one. */
const PLATFORMS = { darwin: "darwin", linux: "linux" };
const ARCHES = { arm64: "arm64", x64: "amd64" };
const OS = PLATFORMS[process.platform] ?? "unsupported";
const ARCH = ARCHES[process.arch] ?? "unsupported";

/** Every external tool the launcher may call; the rig symlinks each one the machine has into its tools dir. */
const TOOLS = [
  "chmod",
  "curl",
  "date",
  "dirname",
  "mkdir",
  "mv",
  "openssl",
  "rm",
  "sha256sum",
  "sh",
  "shasum",
  "sleep",
  "uname",
  "wget",
];

/** One flavour of the launcher: how its dist/run is rendered, and the names it installs and calls. */
const PROVIDER = {
  render: (core) => launcherScript(providerSpec("acme", core)),
  placeholders: ["acme.js", "acme-router.js", "acme-passthrough.js", "acme-ensure.js"],
  homeEnv: "AGENTS_CORE_HOME",
  baseEnv: "CORE_DOWNLOAD_BASE",
  binary: "plugin-core",
  lock: ".plugin-core.fetch.lock",
};

/** The release info for a manifest whose one asset targets this platform; `digest` overrides the asset's
 *  real one. The fake asset matches the flavour's binary name, so its checksum is what lands. */
function info(flavour, digest = createHash("sha256").update(asset(flavour.binary)).digest("hex")) {
  return { ...CORE, sha256: { [`${OS}-${ARCH}`]: digest } };
}

/**
 * A dist dir with the launcher and a bin dir holding fake runtimes that print their name and arguments. The
 * external tools the launcher needs are symlinked into a tools dir (whichever checksum tool and downloader
 * the machine has); /usr/bin itself may hold a node (some CI images), so it stays off PATH. `t` owns the
 * temp dir: everything is removed when the test finishes.
 */
function rig(t, flavour, core, runtimes = [], uname) {
  const dir = realpathSync(mktemp("launcher-"));
  const dist = join(dir, "dist");
  const bin = join(dir, "bin");
  mkdirSync(dist);
  mkdirSync(bin);
  for (const bundle of flavour.placeholders) writeFileSync(join(dist, bundle), "// a bundle the launcher must not run\n");
  const tools = join(dir, "tools");
  mkdirSync(tools);
  for (const tool of TOOLS) {
    const real = spawnSync("/bin/sh", ["-c", `command -v ${tool}`], { encoding: "utf8" }).stdout.trim();
    if (real !== "") symlinkSync(real, join(tools, tool));
  }
  writeFileSync(join(dist, "run"), flavour.render(core));
  for (const name of runtimes) {
    writeFileSync(join(bin, name), `#!/bin/sh\necho ${name} "$@"\n`);
    chmodSync(join(bin, name), 0o755);
  }
  if (uname !== undefined) {
    writeFileSync(join(bin, "uname"), `#!/bin/sh\necho ${uname}\n`);
    chmodSync(join(bin, "uname"), 0o755);
  }
  const binHome = join(dir, "bin-home");
  // Spawned, not spawnSync: a sync spawn would block this process's event loop and with it the asset server a
  // download test serves its fake binary from.
  const run = (args, env = {}) =>
    new Promise((resolve) => {
      const child = spawn("/bin/sh", [join(dist, "run"), ...args], {
        env: { PATH: `${bin}:${tools}`, HOME: join(dir, "home"), [flavour.homeEnv]: binHome, ...env },
      });
      let stdout = "";
      let stderr = "";
      child.stdout.on("data", (chunk) => (stdout += chunk));
      child.stderr.on("data", (chunk) => (stderr += chunk));
      child.on("close", (status) => resolve(ran(status, stdout, stderr)));
    });
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return { dir, dist, bin, binHome, lock: join(binHome, CORE.version, flavour.lock), run };
}

/** A fresh directory under the system temp dir, removed by the caller. */
function mktemp(prefix) {
  return mkdtempSync(join(tmpdir(), prefix));
}

/** A server answering every request with `body`; resolves with its base URL and every path it was asked for. */
async function assetServer(t, body) {
  const urls = [];
  const server = createServer((request, response) => {
    urls.push(request.url ?? "");
    response.end(body);
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const port = server.address().port;
  t.after(() => server.close());
  return { base: `http://127.0.0.1:${port}`, urls };
}

/** An installed binary the launcher execs: the fake asset, executable, under the flavour's home/<version>. */
function install(binHome, flavour) {
  const bin = join(binHome, CORE.version, `${flavour.binary}`);
  mkdirSync(dirname(bin), { recursive: true });
  writeFileSync(bin, asset(flavour.binary));
  chmodSync(bin, 0o755);
  return bin;
}

/** A curl first on PATH that logs its arguments to $CURL_LOG and fails, so a test proves the timeout the
 *  launcher picked without touching the network. Returns the log's path. */
function failingCurl(bin) {
  writeFileSync(join(bin, "curl"), '#!/bin/sh\nprintf \'%s\\n\' "$*" >> "$CURL_LOG"\nexit 22\n');
  chmodSync(join(bin, "curl"), 0o755);
  return join(dirname(bin), "curl.log");
}

/** Resolve true once `probe` passes, or false after `ms` (50 ms steps). */
async function until(probe, ms) {
  const deadline = Date.now() + ms;
  while (!probe()) {
    if (Date.now() >= deadline) return false;
    await new Promise((resolve) => setTimeout(resolve, 50));
  }
  return true;
}

/** A fetch lock in the version dir holding `content`, as a detached download writes "<pid> <epoch seconds>". */
function writeLock(binHome, flavour, content) {
  const dir = join(binHome, CORE.version);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, flavour.lock), `${content}\n`);
}

describe("dist/run", () => {
  it("maps only darwin and linux, and asset names end with the arch", () => {
    const core = { ...CORE, sha256: { "darwin-amd64": "aa", "darwin-arm64": "bb", "linux-amd64": "cc", "linux-arm64": "dd" } };
    for (const spec of [providerSpec("acme", core)]) {
      const script = launcherScript(spec);
      assert.ok(script.includes("Darwin) os=darwin"), "darwin is mapped");
      assert.ok(script.includes("Linux) os=linux"), "linux is mapped");
      const mapped = new Set([...script.matchAll(/\) os=(\w+)/g)].map((m) => m[1]));
      assert.deepEqual([...mapped].filter((os) => os !== "unsupported").sort(), ["darwin", "linux"], `${spec.name}: only darwin and linux are mapped`);
      assert.ok(!/suffix/.test(script), `${spec.name}: asset names carry no suffix`);
    }
  });

  it("runs the installed plugin-core with the provider name, the bundle's entry and every argument", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    install(binHome, PROVIDER);
    assert.deepEqual(await run(["acme.js", "board", "--json", "a b"]), {
      status: 0,
      stdout: "plugin-core acme cli board --json a b\n",
      stderr: "",
    });
  });

  it("maps each bundle name to its entry", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    install(binHome, PROVIDER);
    const entries = [
      ["acme.js", "cli"],
      ["acme-router.js", "router"],
      ["acme-passthrough.js", "passthrough"],
      ["acme-ensure.js", "ensure"],
    ];
    for (const [bundle, entry] of entries)
      assert.equal((await run([bundle])).stdout, `plugin-core acme ${entry}\n`);
  });

  it("setup downloads, checksum-verifies, installs (mode 755) and runs plugin-core", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    const result = await run(["acme.js", "setup", "--json"], { CORE_DOWNLOAD_BASE: base });
    assert.equal(result.status, 0);
    assert.equal(result.stderr, "");
    assert.equal(result.stdout, "plugin-core acme cli setup --json\n");
    assert.deepEqual(urls, [`/core-v9.9.9/plugin-core-${OS}-${ARCH}`]);
    const bin = join(binHome, "9.9.9", `plugin-core`);
    assert.equal(readFileSync(bin, "utf8"), asset("plugin-core"));
    assert.equal(statSync(bin).mode & 0o777, 0o755);
    assert.deepEqual(readdirSync(join(binHome, "9.9.9")), [`plugin-core`]);
  });

  it("a checksum mismatch installs nothing, says why and exits 127", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER, "deadbeef".repeat(8)), ["bun", "node"]);
    const { base } = await assetServer(t, asset("plugin-core"));
    const result = await run(["acme.js", "setup"], { CORE_DOWNLOAD_BASE: base });
    assert.equal(result.status, 127);
    assert.equal(result.stdout, "");
    assert.equal(result.stderr, "acme: plugin-core download failed its checksum\n");
    assert.deepEqual(readdirSync(join(binHome, "9.9.9")), []);
  });

  it("a checksum mismatch under --hook stays silent and exits 0", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER, "deadbeef".repeat(8)), ["bun", "node"]);
    const { base } = await assetServer(t, asset("plugin-core"));
    const result = await run(["acme.js", "setup", "--hook"], { CORE_DOWNLOAD_BASE: base });
    assert.deepEqual(result, ran(0, "", ""));
    assert.deepEqual(readdirSync(join(binHome, "9.9.9")), []);
  });

  it("a download that cannot reach the server exits 127 saying the URL", async (t) => {
    const { run } = rig(t, PROVIDER, info(PROVIDER), ["bun", "node"]);
    const result = await run(["acme.js", "setup"], { CORE_DOWNLOAD_BASE: "http://127.0.0.1:1" });
    assert.equal(result.status, 127);
    assert.equal(result.stdout, "");
    // curl -S reports the connection failure itself; the launcher adds the URL to retry by.
    assert.ok(
      result.stderr.includes(
        `acme: could not download plugin-core 9.9.9 (http://127.0.0.1:1/core-v9.9.9/plugin-core-${OS}-${ARCH})\n`,
      ),
      `stderr says the URL: ${result.stderr}`,
    );
  });

  it("setup --hook downloads with the short timeout and stays silent when it fails", async (t) => {
    const { bin, run } = rig(t, PROVIDER, info(PROVIDER), ["bun", "node"]);
    const log = failingCurl(bin);
    const result = await run(["acme.js", "setup", "--hook"], { CURL_LOG: log });
    assert.deepEqual(result, ran(0, "", ""));
    assert.ok(readFileSync(log, "utf8").includes("--max-time 12 -o"));
  });

  it("a plain setup downloads with the long timeout and says the URL when it fails", async (t) => {
    const { bin, run } = rig(t, PROVIDER, info(PROVIDER), ["bun", "node"]);
    const log = failingCurl(bin);
    const result = await run(["acme.js", "setup"], { CURL_LOG: log });
    assert.equal(result.status, 127);
    assert.equal(result.stdout, "");
    assert.ok(readFileSync(log, "utf8").includes("--max-time 120 -o"));
    assert.ok(
      result.stderr.includes(
        `acme: could not download plugin-core 9.9.9 (https://github.com/MuhmdRaouf/claude-code-plugins` +
          `/releases/download/core-v9.9.9/plugin-core-${OS}-${ARCH})\n`,
      ),
      `stderr says the URL: ${result.stderr}`,
    );
  });

  it("an ensure hook with no binary returns within 1 s and a detached download installs the binary", async (t) => {
    const { binHome, run, lock } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    const started = Date.now();
    const first = await run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base });
    assert.ok(Date.now() - started < 1000, `the hook returned in ${Date.now() - started} ms`);
    assert.deepEqual(first, ran(0, "", ""));
    const dir = join(binHome, "9.9.9");
    const bin = join(dir, `plugin-core`);
    assert.ok(
      await until(() => existsSync(bin) && !existsSync(lock), 10_000),
      "the detached download lands the verified binary",
    );
    assert.equal(readFileSync(bin, "utf8"), asset("plugin-core"));
    assert.equal(statSync(bin).mode & 0o777, 0o755);
    assert.deepEqual(readdirSync(dir), [`plugin-core`]);
    const second = await run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base });
    assert.deepEqual(second, ran(0, "plugin-core acme ensure --hook\n", ""));
    assert.deepEqual(urls, [`/core-v9.9.9/plugin-core-${OS}-${ARCH}`]);
  });

  it("two concurrent ensure hooks start one download between them", async (t) => {
    const { binHome, run, lock } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    const hooks = await Promise.all([
      run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base }),
      run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base }),
    ]);
    for (const hook of hooks) assert.deepEqual(hook, ran(0, "", ""));
    const dir = join(binHome, "9.9.9");
    const bin = join(dir, `plugin-core`);
    assert.ok(
      await until(() => existsSync(bin) && !existsSync(lock), 10_000),
      "one download installs the binary",
    );
    assert.deepEqual(urls, [`/core-v9.9.9/plugin-core-${OS}-${ARCH}`]);
  });

  it("a detached download that fails its checksum leaves no binary and no lock behind", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER, "deadbeef".repeat(8)), ["bun", "node"]);
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    assert.deepEqual(await run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    assert.ok(await until(() => urls.length > 0, 10_000), "the detached fetch reaches the server");
    const dir = join(binHome, "9.9.9");
    // The download happens under the lock, so an empty version dir after it means the fetch cleaned up.
    assert.ok(
      await until(() => existsSync(dir) && readdirSync(dir).length === 0, 10_000),
      "no lock, binary or temp file is left behind",
    );
  });

  it("a non-hook entry with no binary starts no download and keeps its 127", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    const command = await run(["acme.js", "board"], { CORE_DOWNLOAD_BASE: base });
    assert.equal(command.status, 127);
    assert.equal(command.stderr, "acme: plugin-core 9.9.9 is not installed; run /acme:setup\n");
    assert.deepEqual(urls, []);
    assert.equal(existsSync(join(binHome, "9.9.9")), false);
  });

  it("a fetch lock whose holder is dead is taken over by the next ensure hook", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    const dead = spawn("/bin/sh", ["-c", "exit 0"]);
    await new Promise((resolve) => dead.on("close", resolve));
    writeLock(binHome, PROVIDER, `${dead.pid} ${Math.floor(Date.now() / 1000)}`);
    assert.deepEqual(await run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    assert.ok(
      await until(() => existsSync(join(binHome, "9.9.9", `plugin-core`)), 10_000),
      "the hook's fetch takes over the dead lock",
    );
    assert.deepEqual(urls, [`/core-v9.9.9/plugin-core-${OS}-${ARCH}`]);
  });

  it("a fetch lock held by a live, fresh holder starts no second download", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    writeLock(binHome, PROVIDER, `${process.pid} ${Math.floor(Date.now() / 1000)}`);
    assert.deepEqual(await run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    await new Promise((resolve) => setTimeout(resolve, 500));
    assert.deepEqual(urls, []);
    assert.equal(existsSync(join(binHome, "9.9.9", `plugin-core`)), false);
  });

  it("a fetch lock older than 120 s is taken over even though its holder lives", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    const { base, urls } = await assetServer(t, asset("plugin-core"));
    writeLock(binHome, PROVIDER, `${process.pid} ${Math.floor(Date.now() / 1000) - 121}`);
    assert.deepEqual(await run(["acme-ensure.js", "--hook"], { CORE_DOWNLOAD_BASE: base }), ran(0, "", ""));
    assert.ok(
      await until(() => existsSync(join(binHome, "9.9.9", `plugin-core`)), 10_000),
      "the stale lock does not stop the fetch",
    );
    assert.deepEqual(urls, [`/core-v9.9.9/plugin-core-${OS}-${ARCH}`]);
  });

  it("with no binary and no runtime on PATH: a hook exits 0 silently, a command exits 127 asking for setup", async (t) => {
    const { run } = rig(t, PROVIDER, info(PROVIDER));
    assert.deepEqual(await run(["acme-ensure.js", "--hook"]), ran(0, "", ""));
    const command = await run(["acme.js", "board"]);
    assert.equal(command.status, 127);
    assert.equal(command.stderr, "acme: plugin-core 9.9.9 is not installed; run /acme:setup\n");
  });

  it("never runs the JS bundle beside it, whatever runtime is on PATH", async (t) => {
    const { dist, run } = rig(t, PROVIDER, info(PROVIDER), ["bun", "node"]);
    const result = await run(["acme.js", "board"]);
    assert.equal(result.status, 127);
    assert.equal(result.stdout, "");
    assert.notEqual(result.stdout, `bun ${join(dist, "acme.js")} board\n`);
  });

  it("an unknown bundle exits 2 naming it", async (t) => {
    const { binHome, run } = rig(t, PROVIDER, info(PROVIDER));
    install(binHome, PROVIDER);
    const result = await run(["acme-other.js", "setup"]);
    assert.equal(result.status, 2);
    assert.equal(result.stderr, "acme: unknown bundle acme-other.js\n");
  });

  it("an unsupported platform downloads nothing: a hook exits 0, a command 127", async (t) => {
    const { bin, run } = rig(t, PROVIDER, info(PROVIDER), ["bun", "node"], "Foonix");
    const log = failingCurl(bin);
    const hook = await run(["acme.js", "setup", "--hook"], { CURL_LOG: log });
    assert.deepEqual(hook, ran(0, "", ""));
    const command = await run(["acme.js", "setup"], { CURL_LOG: log });
    assert.equal(command.status, 127);
    assert.equal(existsSync(log), false);
  });

  it("providerSpec refuses to generate a launcher with no release to pin", () => {
    assert.throws(() => providerSpec("acme", null), /no plugin-core release/);
  });
});

describe("releaseInfo", () => {
  it("reads the newest manifest by semver and maps its assets to digests", (t) => {
    const dir = mktemp("launcher-release-");
    t.after(() => rmSync(dir, { recursive: true, force: true }));
    writeFileSync(
      join(dir, "v0.9.0.json"),
      JSON.stringify({
        version: "0.9.0",
        tag: "core-v0.9.0",
        assets: { "linux-amd64": { name: "plugin-core-linux-amd64", sha256: "cafe00", size: 1 } },
      }),
    );
    writeFileSync(
      join(dir, "v0.10.0.json"),
      JSON.stringify({
        version: "0.10.0",
        tag: "core-v0.10.0",
        assets: {
          "darwin-arm64": { name: "plugin-core-darwin-arm64", sha256: "abcd00", size: 2 },
          "linux-amd64": { name: "plugin-core-linux-amd64", sha256: "beef00", size: 3 },
        },
      }),
    );
    writeFileSync(join(dir, "notes.txt"), "not a manifest");
    assert.deepEqual(releaseInfo(dir), {
      version: "0.10.0",
      repo: "MuhmdRaouf/claude-code-plugins",
      sha256: { "darwin-arm64": "abcd00", "linux-amd64": "beef00" },
    });
  });

  it("is null while no release manifest exists", (t) => {
    const dir = mktemp("launcher-release-");
    t.after(() => rmSync(dir, { recursive: true, force: true }));
    assert.equal(releaseInfo(join(dir, "none")), null);
    assert.equal(releaseInfo(dir), null);
    writeFileSync(join(dir, "v0.1.0.txt"), "{}");
    assert.equal(releaseInfo(dir), null);
  });
});
